"use strict";(self.webpackChunksedelpeuch_net=self.webpackChunksedelpeuch_net||[]).push([[88285],{69371(e,s,n){n.r(s),n.d(s,{assets:()=>f,contentTitle:()=>m,default:()=>v,frontMatter:()=>p,metadata:()=>c,toc:()=>h});var i=n.cw((e,s)=>{const i=n.p+"assets/images/article-p2-1-90a7f758d43c917b422be90aeae5e4bf.png";n.d(s,["A",0,i])}),t=n.cw((e,s)=>{const i=n.p+"assets/images/article-p3-1-2016bdb0c162c4587fc277672948199e.png";n.d(s,["A",0,i])}),r=n.cw((e,s)=>{const i=n.p+"assets/images/article-p4-1-ecf247546378abc44b85e03dd3c9ff65.png";n.d(s,["A",0,i])}),a=n.cw((e,s)=>{const i=n.p+"assets/images/article-p4-2-b545c19eb6e1c6ea55e61a55986cd8cd.png";n.d(s,["A",0,i])}),l=n.cw((e,s)=>{const i=n.p+"assets/images/article-p5-1-ae2159f18272f0c7aa340ac958d6c26d.png";n.d(s,["A",0,i])}),o=n.cw((e,s)=>{const i=n.p+"assets/images/article-p5-2-88c08ecf8a63c9f086bb295979dc31ce.png";n.d(s,["A",0,i])});const c=JSON.parse('{"id":"scolarite/cpbx/s4/projet/article","title":"Influence des mouvements oculaires sur le P300 Matrix Speller","description":"Article scientifique du projet : protocole sur 15 sujets comparant le P300 Matrix Speller avec et sans fixation de la cible, taux de performance, potentiels \xe9voqu\xe9s visuels, discussion et r\xe9f\xe9rences.","source":"@site/docs/scolarite/cpbx/s4/projet/article.md","sourceDirName":"scolarite/cpbx/s4/projet","slug":"/scolarite/cpbx/s4/projet/article","permalink":"/docs/scolarite/cpbx/s4/projet/article","draft":false,"unlisted":false,"tags":[],"version":"current","lastUpdatedAt":1792955287000,"sidebarPosition":14,"frontMatter":{"title":"Influence des mouvements oculaires sur le P300 Matrix Speller","description":"Article scientifique du projet : protocole sur 15 sujets comparant le P300 Matrix Speller avec et sans fixation de la cible, taux de performance, potentiels \xe9voqu\xe9s visuels, discussion et r\xe9f\xe9rences.","sidebar_position":14},"sidebar":"tutorialSidebar","previous":{"title":"Gestion du projet","permalink":"/docs/scolarite/cpbx/s4/projet/gestion-du-projet"},"next":{"title":"ENSEIRB-MATMECA","permalink":"/docs/scolarite/enseirb/"}}');var u=n(74848),d=n(28453);const p={title:"Influence des mouvements oculaires sur le P300 Matrix Speller",description:"Article scientifique du projet : protocole sur 15 sujets comparant le P300 Matrix Speller avec et sans fixation de la cible, taux de performance, potentiels \xe9voqu\xe9s visuels, discussion et r\xe9f\xe9rences.",sidebar_position:14},m=void 0,f={},h=[{value:"Introduction",id:"introduction",level:2},{value:"M\xe9thode",id:"m\xe9thode",level:2},{value:"Description de l&#39;exp\xe9rience, hypoth\xe8ses",id:"description-de-lexp\xe9rience-hypoth\xe8ses",level:3},{value:"Choix de la cohorte",id:"choix-de-la-cohorte",level:3},{value:"Paradigme",id:"paradigme",level:3},{value:"Acquisition et traitement des donn\xe9es",id:"acquisition-et-traitement-des-donn\xe9es",level:3},{value:"V\xe9rification",id:"v\xe9rification",level:3},{value:"R\xe9sultats",id:"r\xe9sultats",level:2},{value:"Comparaison des taux de performance",id:"comparaison-des-taux-de-performance",level:3},{value:"Influence de la distance entre la position du caract\xe8re cible et le centre de l&#39;\xe9cran",id:"influence-de-la-distance-entre-la-position-du-caract\xe8re-cible-et-le-centre-de-l\xe9cran",level:3},{value:"Influence des mouvements oculaires sur l&#39;apparition des marqueurs physiologiques",id:"influence-des-mouvements-oculaires-sur-lapparition-des-marqueurs-physiologiques",level:3},{value:"Discussion",id:"discussion",level:2},{value:"Conclusion",id:"conclusion",level:2},{value:"R\xe9f\xe9rences",id:"r\xe9f\xe9rences",level:2}];function x(e){const s={em:"em",h2:"h2",h3:"h3",img:"img",li:"li",ol:"ol",p:"p",strong:"strong",ul:"ul",...(0,d.R)(),...e.components},{Katex:n}=s;return n||function(e,s){throw new Error("Expected "+(s?"component":"object")+" `"+e+"` to be defined: you likely forgot to import, pass, or provide it.")}("Katex",!0),(0,u.jsxs)(u.Fragment,{children:[(0,u.jsxs)(s.p,{children:[(0,u.jsx)(s.strong,{children:'Influence des mouvements oculaires sur la performance du "P300 Matrix Speller".'})," Article r\xe9dig\xe9 par S\xe9bastien Delpeuch, Valentin Escobosa et Natacha Javerzat, Cycle Pr\xe9paratoire de Bordeaux, Universit\xe9 de Bordeaux, 11 avril 2019."]}),"\n",(0,u.jsxs)(s.p,{children:[(0,u.jsx)(s.strong,{children:"R\xe9sum\xe9."})," De nombreux troubles neuromusculaires engendrent une inaptitude partielle ou totale de la personne atteinte \xe0 la communication. Les interfaces cerveau-machine (ICM) offrent une alternative \xe0 ces personnes en reliant directement leur activit\xe9 c\xe9r\xe9brale \xe0 l'action \xe0 effectuer, sans intervention des muscles. Par l'interm\xe9diaire de ces interfaces, il est donc possible de recr\xe9er une forme de communication, g\xe9n\xe9ralement \xe9crite. Le \"P300 Matrix Speller\" a \xe9t\xe9 pens\xe9 en ce sens. Il s'agit d'une ICM permettant \xe0 l'utilisateur de communiquer en inscrivant des lettres sur un \xe9cran, et ce en utilisant exclusivement son activit\xe9 c\xe9r\xe9brale. Il a \xe9t\xe9 commun\xe9ment admis que la performance de ce syst\xe8me ne d\xe9pend pas de la capacit\xe9 de l'utilisateur \xe0 voir et \xe0 fixer la lettre qu'il souhaite \xe9crire. Plus pr\xe9cis\xe9ment, il a \xe9t\xe9 suppos\xe9 que les composantes visuelles pr\xe9sentes dans l'activit\xe9 c\xe9r\xe9brale utilis\xe9e par la machine n'affectent pas sa fiabilit\xe9 de mani\xe8re significative. Cette hypoth\xe8se est cependant sujette \xe0 d\xe9bat, ce qui soul\xe8ve de nombreuses interrogations quant aux possibles applications cliniques. L'objectif de notre \xe9tude \xe9tait d'estimer l'influence des mouvements oculaires sur les performances du P300 Speller."]}),"\n",(0,u.jsx)(s.p,{children:"Nous avons men\xe9 une exp\xe9rience sur une cohorte de 15 sujets sains. Notre protocole consistait \xe0 comparer les performances du P300 Speller lors de deux sc\xe9narios distincts. Dans un premier temps, les sujets utilisaient le P300 Speller de mani\xe8re conventionnelle (le regard \xe9tait port\xe9 sur la lettre cible). Dans un second temps, les sujets devaient fixer leur regard sur un \xe9l\xe9ment tiers tout en se concentrant mentalement sur la lettre qu'ils souhaitaient \xe9crire."}),"\n",(0,u.jsx)(s.p,{children:"Nos r\xe9sultats ont montr\xe9 que le taux de performance est bien plus \xe9lev\xe9 lorsque le caract\xe8re cible est fix\xe9 par l'utilisateur. Notre exp\xe9rience sugg\xe8re que la fiabilit\xe9 du P300 Matrix Speller d\xe9pend significativement de l'emplacement du regard, ce qui va \xe0 l'encontre des hypoth\xe8ses \xe9nonc\xe9es pr\xe9c\xe9demment. Les relations entre nos r\xe9sultats et les taux de performance qu'obtiendrait le P300 Speller aupr\xe8s d'une personne atteinte de troubles oculomoteurs restent ind\xe9termin\xe9es. M\xeame si nous pouvons raisonnablement affirmer que la fiabilit\xe9 serait affect\xe9e, des \xe9tudes suppl\xe9mentaires sont n\xe9cessaires pour pouvoir estimer dans quelle mesure et pourquoi."}),"\n",(0,u.jsxs)(s.p,{children:[(0,u.jsx)(s.strong,{children:"Mots cl\xe9s."})," ICM, P300, Potentiel \xc9voqu\xe9 Visuel, P300 Matrix Speller"]}),"\n",(0,u.jsx)(s.h2,{id:"introduction",children:"Introduction"}),"\n",(0,u.jsx)(s.p,{children:"De nombreux troubles neuromusculaires engendrent l'inaptitude totale ou partielle de la personne atteinte \xe0 la communication. Ces troubles sont dus \xe0 des accidents vasculaires, des atteintes \xe0 la moelle \xe9pini\xe8re ou encore \xe0 des maladies comme la Scl\xe9rose Lat\xe9rale Amyotrophique (SLA). Ils se traduisent par des paralysies plus ou moins importantes sur l'ensemble du corps. Aux stades les plus avanc\xe9s de la SLA, la paralysie des muscles entourant les yeux (muscles oculomoteurs) emp\xeache l'utilisation des moyens de communication bas\xe9s sur la commande oculaire. Divers probl\xe8mes cliniques en r\xe9sultent. On peut, entre autres, soulever la question du consentement et la difficult\xe9 \xe0 estimer la douleur chez la personne. La fabrication d'un syst\xe8me permettant d'\xe9crire sans aucune intervention des muscles constituerait une alternative pour ces patients. Or, ces \"machines \xe0 \xe9crire mentales\", sollicitant uniquement l'activit\xe9 c\xe9r\xe9brale pour fonctionner, existent d\xe9j\xe0. Il s'agit d'interfaces cerveau-machine, g\xe9n\xe9ralement visuelles. La plus connue et la plus utilis\xe9e de ces interfaces \xe0 ce jour est le \"P300 Matrix Speller\"."}),"\n",(0,u.jsx)(s.p,{children:"Originellement introduit par L. Farwell et E. Donchin en 1988, le P300 Matrix Speller base son fonctionnement sur la d\xe9tection d'une singularit\xe9 dans l'activit\xe9 c\xe9r\xe9brale. Cette singularit\xe9 prend la forme d'une onde d'amplitude caract\xe9ristique appel\xe9e potentiel P300. Son apparition est interpr\xe9t\xe9e comme la cons\xe9quence d'\xe9tats mentaux particuliers. Dans le cas du P300 Matrix Speller, on montre que la P300 survient lorsque le caract\xe8re cible, c'est-\xe0-dire la lettre ou le chiffre que l'on veut inscrire, est pr\xe9sent\xe9 \xe0 l'utilisateur."}),"\n",(0,u.jsx)(s.p,{children:"Afin d'optimiser l'apparition de la P300 lors de l'utilisation du syst\xe8me, un paradigme de stimulation a \xe9t\xe9 mis au point. Ce paradigme (Row-Column Paradigm) se pr\xe9sente sous la forme d'une matrice, affich\xe9e sur un \xe9cran et dans laquelle sont r\xe9pertori\xe9s les diff\xe9rents caract\xe8res (lettres et chiffres) n\xe9cessaires \xe0 l'\xe9criture. Lorsque le P300 Speller fonctionne, les lignes et les colonnes de la matrice s'illuminent successivement, dans un clignotement tr\xe8s rapide. L'utilisateur est suppos\xe9 fixer le caract\xe8re souhait\xe9. L'illumination du caract\xe8re cible initie la r\xe9ponse P300."}),"\n",(0,u.jsx)(s.p,{children:"Lors des premi\xe8res exp\xe9riences de P300 Matrix Speller, il a \xe9t\xe9 admis que l'onde P300 est le principal marqueur visible par \xe9lectroenc\xe9phalographie, au point de n\xe9gliger les autres composantes du signal. Ainsi, les composantes visuelles, traditionnellement consid\xe9r\xe9es comme mineures, ne sont pas suppos\xe9es influencer la performance du syst\xe8me. Cette affirmation est aujourd'hui remise en cause, notamment par les cliniciens. De nombreux enjeux m\xe9dicaux en d\xe9coulent."}),"\n",(0,u.jsx)(s.p,{children:"L'objectif de notre exp\xe9rience \xe9tait d'estimer l'influence des mouvements oculaires sur les performances du P300 Speller afin de valider, ou d'invalider, l'hypoth\xe8se de L. Farwell et E. Donchin."}),"\n",(0,u.jsx)(s.h2,{id:"m\xe9thode",children:"M\xe9thode"}),"\n",(0,u.jsx)(s.h3,{id:"description-de-lexp\xe9rience-hypoth\xe8ses",children:"Description de l'exp\xe9rience, hypoth\xe8ses"}),"\n",(0,u.jsx)(s.p,{children:"Nous avons \xe9valu\xe9 les performances du P300 Matrix Speller dans le cadre de deux sc\xe9narios distincts."}),"\n",(0,u.jsxs)(s.ul,{children:["\n",(0,u.jsx)(s.li,{children:"Sc\xe9nario n\xb0 1 : le speller fonctionne de mani\xe8re conventionnelle, c'est-\xe0-dire que l'utilisateur fixe son regard sur le caract\xe8re cible."}),"\n",(0,u.jsx)(s.li,{children:"Sc\xe9nario n\xb0 2 : l'utilisateur a pour consigne de fixer son regard sur une croix affich\xe9e au centre de l'\xe9cran et de ne pas le d\xe9placer pendant toute la dur\xe9e de l'exp\xe9rience. Il se concentre donc sur le caract\xe8re cible de mani\xe8re exclusivement mentale."}),"\n"]}),"\n",(0,u.jsx)(s.p,{children:"Except\xe9 la pr\xe9sence de la croix dans le sc\xe9nario 2, la matrice utilis\xe9e pour la stimulation n'a pas \xe9t\xe9 modifi\xe9e. Nous avons consid\xe9r\xe9 les deux hypoth\xe8ses suivantes :"}),"\n",(0,u.jsxs)(s.ul,{children:["\n",(0,u.jsx)(s.li,{children:"Lorsque la lettre cible est fix\xe9e normalement par l'utilisateur, les deux composantes (visuelle et P300) sont initi\xe9es (sc\xe9nario 1). Lorsque l'utilisateur regarde dans une autre direction, fixe et inchang\xe9e, seule la composante P300 est initi\xe9e (sc\xe9nario 2)."}),"\n",(0,u.jsx)(s.li,{children:"Le montage optimis\xe9 pour le P300 Speller en fonctionnement normal est sous-optimal lorsque les yeux ne fixent pas la cible. Une meilleure performance est donc attendue dans le sc\xe9nario 1."}),"\n"]}),"\n",(0,u.jsx)(s.h3,{id:"choix-de-la-cohorte",children:"Choix de la cohorte"}),"\n",(0,u.jsx)(s.p,{children:"Notre cohorte \xe9tait compos\xe9e de 15 sujets diff\xe9rents, 5 femmes et 10 hommes. Ils sont \xe2g\xe9s de 20 \xe0 62 ans, ont une vision normale ou normale corrig\xe9e et sont tous droitiers. Ils ont \xe9t\xe9 inform\xe9s du protocole et sont familiaris\xe9s avec le fonctionnement conventionnel du P300 Speller."}),"\n",(0,u.jsx)(s.h3,{id:"paradigme",children:"Paradigme"}),"\n",(0,u.jsx)(s.p,{children:(0,u.jsx)(s.img,{alt:"Figure 1 : montage exp\xe9rimental",src:i().A+"",width:"401",height:"168"})}),"\n",(0,u.jsxs)(s.p,{children:["Les sujets ont \xe9t\xe9 plac\xe9s \xe0 une distance de 60 cm de l'\xe9cran o\xf9 \xe9tait affich\xe9e la matrice. Celle-ci pr\xe9sentait 6 lignes et 6 colonnes et comprenait 36 caract\xe8res au total (lettres et chiffres). Consid\xe9rant la distance \xe0 l'\xe9cran, il a \xe9t\xe9 admis que la matrice occupait un angle de ",(0,u.jsx)(n,{tex:"\\pm 7{,}1\xb0"})," de l'ensemble du champ visuel."]}),"\n",(0,u.jsx)(s.p,{children:"La direction du regard des utilisateurs a \xe9t\xe9 mesur\xe9e par un syst\xe8me de suivi oculaire (eye-tracker) int\xe9gr\xe9 \xe0 l'\xe9cran, \xe0 une fr\xe9quence de 60 estimations par seconde. Les coordonn\xe9es obtenues ont \xe9t\xe9 int\xe9gr\xe9es dans l'acquisition des donn\xe9es et \xe9galement utilis\xe9es lors de l'analyse post-exp\xe9rimentale."}),"\n",(0,u.jsxs)(s.p,{children:["La dur\xe9e totale de l'exp\xe9rience \xe9tait de deux heures par individu. Chaque sujet a test\xe9 les deux sc\xe9narios successivement. Dans le sc\xe9nario 2, la croix \xe9tait color\xe9e et son intensit\xe9 lumineuse \xe9tait similaire \xe0 celle des autres \xe9l\xe9ments de la matrice. Si le sujet d\xe9pla\xe7ait son regard de plus de ",(0,u.jsx)(n,{tex:"2{,}8\xb0"})," par rapport \xe0 la croix, et ce pendant plus de 300 ms, celle-ci effectuait un mouvement rotatif \xe0 45\xb0. L'utilisateur \xe9tait donc inform\xe9 lorsqu'il devait recentrer son regard."]}),"\n",(0,u.jsx)(s.p,{children:"Les sujets ont effectu\xe9 au total 24 sessions (12 par sc\xe9nario). Chaque session comportait 4 essais, c'est-\xe0-dire que 4 \xe9l\xe9ments cibles ont \xe9t\xe9 successivement propos\xe9s \xe0 l'utilisateur. Lors de chaque essai, les lignes et les colonnes de la matrice ont \xe9t\xe9 illumin\xe9es 15 fois respectivement. Chaque illumination durait 125 ms et \xe9tait suivie par un intervalle de 125 ms \xe9galement. Une pause de 8 secondes entre les essais a \xe9t\xe9 instaur\xe9e, afin que le sujet puisse se concentrer sur la nouvelle cible."}),"\n",(0,u.jsx)(s.h3,{id:"acquisition-et-traitement-des-donn\xe9es",children:"Acquisition et traitement des donn\xe9es"}),"\n",(0,u.jsx)(s.p,{children:"L'acquisition et le traitement des donn\xe9es ont \xe9t\xe9 effectu\xe9s par l'interm\xe9diaire du logiciel BCI2000 [1] [2]."}),"\n",(0,u.jsxs)(s.p,{children:[(0,u.jsx)(s.strong,{children:"A. Acquisition des donn\xe9es : m\xe9thode d'\xe9lectroenc\xe9phalographie."})," L'activit\xe9 c\xe9r\xe9brale de l'utilisateur a \xe9t\xe9 enregistr\xe9e par l'interm\xe9diaire de 8 \xe9lectrodes (Fz, Cz, P3, Pz, P4, PO7, Oz, PO8), dispos\xe9es \xe0 la surface du cuir chevelu. Deux \xe9lectrodes, plac\xe9es au niveau des apophyses masto\xefdes, servaient respectivement d'\xe9lectrode de masse et d'\xe9lectrode de r\xe9f\xe9rence."]}),"\n",(0,u.jsx)(s.p,{children:(0,u.jsx)(s.img,{alt:"Figure 2 : choix des \xe9lectrodes pour un montage \xe0 8 canaux",src:t().A+"",width:"325",height:"325"})}),"\n",(0,u.jsx)(s.p,{children:"Dans le m\xeame temps, les diff\xe9rences de potentiel entre \xe9lectrodes ont \xe9t\xe9 mesur\xe9es. Ces donn\xe9es ont \xe9t\xe9 utilis\xe9es pour construire des images de cartographie fonctionnelle c\xe9r\xe9brale. Les donn\xe9es de l'eye-tracker ont \xe9galement \xe9t\xe9 acquises."}),"\n",(0,u.jsxs)(s.p,{children:[(0,u.jsx)(s.strong,{children:"B. Traitement des donn\xe9es."})," Lors de l'extraction des donn\xe9es, nous avons effectu\xe9 un filtrage spectral du signal entre 0,1 et 20 Hz, puis un sous-\xe9chantillonnage \xe0 40 Hz. Consid\xe9rant que la r\xe9ponse s'\xe9tendait de 0 \xe0 750 ms apr\xe8s pr\xe9sentation du stimulus cible, nous devions consid\xe9rer 30 caract\xe9ristiques par \xe9lectrode (",(0,u.jsx)(n,{tex:"40 \\times 0{,}75 = 30"}),"), c'est-\xe0-dire 240 caract\xe9ristiques pour l'ensemble du montage."]}),"\n",(0,u.jsx)(s.p,{children:"Avant de proc\xe9der \xe0 la classification, c'est-\xe0-dire \xe0 la discrimination entre les stimulus cibles et non cibles, nous avons utilis\xe9 une m\xe9thode de r\xe9gression s\xe9quentielle [3]. Cette m\xe9thode nous a permis de r\xe9duire le nombre de caract\xe9ristiques \xe0 consid\xe9rer \xe0 un maximum de 60 caract\xe9ristiques pour l'ensemble du montage. La classification a ensuite \xe9t\xe9 effectu\xe9e par l'interm\xe9diaire d'un mod\xe8le lin\xe9aire [4]. Le classifieur a \xe9t\xe9 entra\xeen\xe9 et \xe9valu\xe9 avant chaque utilisation par un nouveau sujet."}),"\n",(0,u.jsx)(s.h3,{id:"v\xe9rification",children:"V\xe9rification"}),"\n",(0,u.jsx)(s.p,{children:"Les deux sc\xe9narios ont \xe9t\xe9 pens\xe9s pour estimer des diff\xe9rences de performances dues aux mouvements oculaires. Il \xe9tait donc essentiel de v\xe9rifier que les sujets fixaient respectivement la cible dans le sc\xe9nario 1 ou la croix dans le sc\xe9nario 2."}),"\n",(0,u.jsx)(s.p,{children:"Dans le sc\xe9nario 2, les sujets \xe9taient alert\xe9s si leur regard se d\xe9pla\xe7ait de mani\xe8re significative. Toutefois, le cas \xe9ch\xe9ant, leur essai n'\xe9tait pas arr\xeat\xe9."}),"\n",(0,u.jsx)(s.p,{children:"Une v\xe9rification post-exp\xe9rimentale a \xe9t\xe9 men\xe9e."}),"\n",(0,u.jsx)(s.p,{children:(0,u.jsx)(s.img,{alt:"Figure 3 : repr\xe9sentation de la distribution des distances entre le point fix\xe9 \xe0 l&#39;\xe9cran et le centre de l&#39;\xe9cran, pour les deux sc\xe9narios",src:r().A+"",width:"378",height:"334"})}),"\n",(0,u.jsx)(s.p,{children:"Les r\xe9sultats obtenus ont permis de repr\xe9senter la distribution des distances entre le point fix\xe9 \xe0 l'\xe9cran et le centre de l'\xe9cran enregistr\xe9es par l'eye-tracker. La courbe relative au sc\xe9nario 2, en bleu, pr\xe9sente un unique pic centr\xe9 en 0. On en d\xe9duit que le sujet s'est effectivement focalis\xe9 sur la croix. La courbe relative au sc\xe9nario 1, en rouge, pr\xe9sente 6 petits pics r\xe9guliers. Chaque pic est centr\xe9 sur une colonne. On en d\xe9duit que le sujet s'est concentr\xe9 sur les 6 colonnes de mani\xe8re uniforme. On peut donc conclure que le sujet a correctement effectu\xe9 les deux sc\xe9narios et que les donn\xe9es sont exploitables."}),"\n",(0,u.jsx)(s.h2,{id:"r\xe9sultats",children:"R\xe9sultats"}),"\n",(0,u.jsx)(s.h3,{id:"comparaison-des-taux-de-performance",children:"Comparaison des taux de performance"}),"\n",(0,u.jsx)(s.p,{children:"La performance de la classification (i.e. la fiabilit\xe9 \xe0 diff\xe9rencier correctement un stimulus cible d'un stimulus non-cible) est plus \xe9lev\xe9e lorsque le speller est utilis\xe9 de mani\xe8re conventionnelle."}),"\n",(0,u.jsx)(s.p,{children:"La fiabilit\xe9 de la classification apr\xe8s 15 r\xe9p\xe9titions du stimulus se situe entre 80 % et 100 % pour le sc\xe9nario 1 et entre 2,8 % et 90 % pour le sc\xe9nario 2. La fiabilit\xe9 de la classification dans le sc\xe9nario 2 est donc sujette \xe0 une importante variabilit\xe9."}),"\n",(0,u.jsx)(s.p,{children:"Les analyses post-exp\xe9rimentales ont montr\xe9 que les cibles ont \xe9t\xe9 correctement identifi\xe9es (100 % de fiabilit\xe9) pour 53 % des sujets dans le sc\xe9nario 1. Dans le sc\xe9nario 2, une fiabilit\xe9 de 100 % n'a jamais \xe9t\xe9 atteinte. Une fiabilit\xe9 de 50 % a cependant \xe9t\xe9 obtenue pour 47 % des sujets."}),"\n",(0,u.jsx)(s.h3,{id:"influence-de-la-distance-entre-la-position-du-caract\xe8re-cible-et-le-centre-de-l\xe9cran",children:"Influence de la distance entre la position du caract\xe8re cible et le centre de l'\xe9cran"}),"\n",(0,u.jsx)(s.p,{children:"Les donn\xe9es enregistr\xe9es par l'eye-tracker permettent d'estimer l'influence, sur la classification, de la distance entre la position du caract\xe8re que l'utilisateur souhaite inscrire et le centre de l'\xe9cran. Les donn\xe9es de la figure 4 montrent que la courbe correspondant au sc\xe9nario 1 (en rouge) est pratiquement constante. La fiabilit\xe9 de la classification ne varie donc pas significativement selon la position du caract\xe8re souhait\xe9. Au contraire, la courbe correspondant au sc\xe9nario 2 (en bleu) t\xe9moigne d'une importante diminution de la fiabilit\xe9 de la classification \xe0 mesure que l'on s'\xe9loigne du centre de l'\xe9cran. La variation de la distance entre la position du caract\xe8re cible et le centre de l'\xe9cran influe donc sur la fiabilit\xe9 de la classification dans le sc\xe9nario 2, mais pas dans le sc\xe9nario 1."}),"\n",(0,u.jsx)(s.p,{children:(0,u.jsx)(s.img,{alt:"Figure 4 : fiabilit\xe9 de la classification en fonction de la distance au centre du caract\xe8re cible",src:a().A+"",width:"399",height:"302"})}),"\n",(0,u.jsx)(s.h3,{id:"influence-des-mouvements-oculaires-sur-lapparition-des-marqueurs-physiologiques",children:"Influence des mouvements oculaires sur l'apparition des marqueurs physiologiques"}),"\n",(0,u.jsx)(s.p,{children:"La fiabilit\xe9 du P300 Matrix Speller est significativement meilleure dans le cas du premier sc\xe9nario. Nous avons cherch\xe9 \xe0 expliquer cet \xe9cart de performance d'un point de vue physiologique. Pour cela, nous avons compar\xe9 l'activit\xe9 c\xe9r\xe9brale enregistr\xe9e lors des deux sc\xe9narios."}),"\n",(0,u.jsx)(s.p,{children:"Nous disposons des donn\xe9es d'\xe9lectroenc\xe9phalographie relatives \xe0 chaque exp\xe9rience. En moyennant les r\xe9ponses obtenues dans un sc\xe9nario \xe0 la suite d'un stimulus cible, l'allure d'une r\xe9ponse \"type\" a pu \xeatre mod\xe9lis\xe9e, et ce pour chaque \xe9lectrode. Cette mod\xe9lisation nous a permis de comparer l'allure de la r\xe9ponse \xe0 un stimulus cible dans les sc\xe9narios 1 et 2."}),"\n",(0,u.jsx)(s.p,{children:(0,u.jsx)(s.img,{alt:"Figure 5 : r\xe9ponses moyennes enregistr\xe9es par EEG",src:l().A+"",width:"401",height:"334"})}),"\n",(0,u.jsx)(s.p,{children:"Les premiers signaux visibles sur l'\xe9lectroenc\xe9phalographe dans le cas du sc\xe9nario 1 apparaissent d\xe8s 180 ms apr\xe8s le stimulus cible, et sont suivis par le potentiel P300. La r\xe9ponse dans le cas du sc\xe9nario 2 est plus tardive et l'amplitude du potentiel P300 moins importante. Les signaux pr\xe9coces observ\xe9s sur l'\xe9lectroenc\xe9phalographe du sc\xe9nario 1 sont absents des donn\xe9es relatives au sc\xe9nario 2."}),"\n",(0,u.jsx)(s.p,{children:(0,u.jsx)(s.img,{alt:"Figure 6 : images de cartographie fonctionnelle correspondantes",src:o().A+"",width:"401",height:"279"})}),"\n",(0,u.jsx)(s.p,{children:"Dans le cas du sc\xe9nario 1, les donn\xe9es de cartographie fonctionnelle c\xe9r\xe9brale montrent une excitation des zones visuelles et occipitales de l'enc\xe9phale, puis des zones centro-pari\xe9tales. Ces images illustrent l'apparition d'un PEV (Potentiel \xc9voqu\xe9 Visuel) pr\xe9c\xe9dant l'apparition de l'onde P300. Le PEV est absent des donn\xe9es de cartographie c\xe9r\xe9brale du sc\xe9nario 2."}),"\n",(0,u.jsx)(s.p,{children:"Il s'agit ensuite d'estimer l'impact de la composante visuelle sur la fiabilit\xe9 de la classification. Nous avons simul\xe9 une nouvelle classification, selon les m\xeames crit\xe8res d'analyse que pr\xe9c\xe9demment, mais en excluant les donn\xe9es provenant des signaux les plus pr\xe9coces (situ\xe9s entre 0 et 250 ms apr\xe8s le stimulus). Les r\xe9sultats montrent une r\xe9duction significative de la fiabilit\xe9 de la classification dans le cas du sc\xe9nario 1, mais pas de changement significatif dans le sc\xe9nario 2."}),"\n",(0,u.jsx)(s.h2,{id:"discussion",children:"Discussion"}),"\n",(0,u.jsx)(s.p,{children:"Lorsque le caract\xe8re cible est regard\xe9 par l'utilisateur (sc\xe9nario 1), le taux de fiabilit\xe9 du speller est \xe9lev\xe9 et le syst\xe8me est optimal. Au contraire, lorsque le regard de l'utilisateur est port\xe9 sur un \xe9l\xe9ment autre que le caract\xe8re cible et dont la position ne varie pas au cours du temps (sc\xe9nario 2), la performance du speller devient mauvaise."}),"\n",(0,u.jsx)(s.p,{children:"Cet \xe9cart de performance s'explique d'abord par le fait que, dans le sc\xe9nario 2, la fiabilit\xe9 d\xe9cro\xeet \xe0 mesure que la distance entre la position du caract\xe8re cible et le centre de l'\xe9cran augmente. De telles variations de fiabilit\xe9 n'apparaissent pas dans le sc\xe9nario 1."}),"\n",(0,u.jsx)(s.p,{children:"Cependant, des analyses plus pouss\xe9es montrent que les \xe9carts de performance entre le sc\xe9nario 1 et le sc\xe9nario 2 sont essentiellement dus \xe0 des diff\xe9rences physiologiques. Nous avons en effet observ\xe9 des signaux pr\xe9coces sur l'\xe9lectroenc\xe9phalographe du sc\xe9nario 1 qui sont totalement absents de l'\xe9lectroenc\xe9phalographe du sc\xe9nario 2. Lorsque ces signaux sont virtuellement supprim\xe9s de l'\xe9lectroenc\xe9phalographe du sc\xe9nario 1, le taux de performance chute. En corr\xe9lant l'instant de leur apparition aux images de cartographie c\xe9r\xe9brale, on montre que ces signaux sont des PEV (Potentiels \xc9voqu\xe9s Visuels). Les PEV d\xe9pendent de l'int\xe9grit\xe9 du syst\xe8me visuel. On en d\xe9duit que le P300 Speller d\xe9pend en effet de l'apparition de l'onde P300 lors de la reconnaissance du stimulus cible, mais \xe9galement d'une composante visuelle, initi\xe9e lorsque le caract\xe8re d\xe9sir\xe9 est illumin\xe9."}),"\n",(0,u.jsx)(s.p,{children:"Il a \xe9t\xe9 montr\xe9 que le cortex visuel effectue des traitements complexes de divers facteurs spatio-temporels (mouvement, fr\xe9quence spatiale, vitesse...) [5]. D'apr\xe8s Martens et al. 2009, ces propri\xe9t\xe9s peuvent \xeatre exploit\xe9es pour augmenter l'amplitude de la r\xe9ponse sur l'\xe9lectroenc\xe9phalographe et donc, par extension, la fiabilit\xe9 de la classification [6]."}),"\n",(0,u.jsx)(s.p,{children:"Deux aspects de la m\xe9thode utilis\xe9e lors de cette \xe9tude peuvent avoir exag\xe9r\xe9 la r\xe9elle diff\xe9rence de fiabilit\xe9 entre les deux sc\xe9narios."}),"\n",(0,u.jsxs)(s.ul,{children:["\n",(0,u.jsx)(s.li,{children:"Le sc\xe9nario 2 est une t\xe2che plus complexe, demandant plus d'attention et d'\xe9nergie de la part de l'utilisateur. De plus, les sujets n'\xe9taient pas familiaris\xe9s avec ce sc\xe9nario, contrairement au sc\xe9nario 1. Avec un certain entra\xeenement, on peut supposer que leurs performances sur le sc\xe9nario 2 auraient \xe9t\xe9 meilleures."}),"\n",(0,u.jsx)(s.li,{children:"Dans le sc\xe9nario 2, certains caract\xe8res \xe9taient \"d\xe9savantag\xe9s\" en tant que cible, car plus \xe9loign\xe9s de la croix centrale que d'autres. Un nombre important d'erreurs \xe9tait donc attendu. On peut supposer qu'avec une disposition des caract\xe8res en cercle autour de la croix centrale, la diff\xe9rence de fiabilit\xe9 entre les deux sc\xe9narios aurait \xe9t\xe9 moins marqu\xe9e."}),"\n"]}),"\n",(0,u.jsx)(s.p,{children:"Enfin, il est \xe0 noter que, lorsque nous avons effectu\xe9 les contr\xf4les sur les mouvements oculaires, nous n'avons pas contr\xf4l\xe9 les mouvements tr\xe8s brefs. Ces mouvements (micro-saccades) contribuent \xe0 la stimulation des neurones dans les aires visuelles primaires. M\xeame s'il est connu que la SLA peut rendre impossibles les mouvements oculaires, son effet sur les micro-saccades n'a pas encore \xe9t\xe9 \xe9tudi\xe9. Les r\xe9sultats annonc\xe9s ici et les r\xe9sultats attendus pour les patients souffrant de SLA ne peuvent donc pas \xeatre directement reli\xe9s."}),"\n",(0,u.jsx)(s.h2,{id:"conclusion",children:"Conclusion"}),"\n",(0,u.jsx)(s.p,{children:"L'\xe9tude montre que la fiabilit\xe9 du P300 Matrix Speller est affect\xe9e par les mouvements oculaires. En effet, nos r\xe9sultats ont montr\xe9 que la performance de l'interface d\xe9pend significativement de l'int\xe9grit\xe9 du syst\xe8me visuel. Plus pr\xe9cis\xe9ment, la performance est affect\xe9e lorsque la composante visuelle de la r\xe9ponse au stimulus (PEV) ne peut \xeatre initi\xe9e."}),"\n",(0,u.jsx)(s.p,{children:"Ceci sugg\xe8re que les performances d'un speller bas\xe9 uniquement sur l'apparition de la P300 seront significativement alt\xe9r\xe9es si l'utilisateur n'est pas en mesure de fixer le caract\xe8re cible. L'hypoth\xe8se de L. Farwell et E. Donchin est donc invalid\xe9e."}),"\n",(0,u.jsx)(s.p,{children:"Nos r\xe9sultats sont coh\xe9rents avec le fait que la performance du P300 Speller chute lors de l'utilisation par des patients atteints de SLA. Des recherches plus pouss\xe9es doivent cependant \xeatre men\xe9es aupr\xe8s de ces populations afin d'en \xe9tablir les causes pr\xe9cises. La connaissance de ces m\xe9canismes pourrait permettre, \xe0 terme, d'optimiser un montage en vue d'un usage clinique."}),"\n",(0,u.jsx)(s.h2,{id:"r\xe9f\xe9rences",children:"R\xe9f\xe9rences"}),"\n",(0,u.jsxs)(s.ol,{children:["\n",(0,u.jsxs)(s.li,{children:["Schalk, Gerwin, McFarland, Dennis J., Hinterberger, Thilo, Birbaumer, Niels et Wolpaw, Jonathan R. ",(0,u.jsx)(s.em,{children:"BCI2000 : A general-purpose brain-computer interface (BCI) system"}),". IEEE Transactions on Biomedical Engineering, vol. 51, no 6, page 10, juin 2004."]}),"\n",(0,u.jsxs)(s.li,{children:["Schalk, Gerwin et Mellinger, J\xfcrgen. ",(0,u.jsx)(s.em,{children:"A practical guide to brain-computer interfacing with BCI2000"}),". Springer, 2010."]}),"\n",(0,u.jsxs)(s.li,{children:["Jennrich, R.I., Wiley, John and Sons. ",(0,u.jsx)(s.em,{children:"New York"}),". p. 58-75, 1977."]}),"\n",(0,u.jsxs)(s.li,{children:["Krusienski D.J., Sellers E.W., Cabestaing F., Bayoudh S., McFarland D.J., Vaughan T.M. et Wolpaw J.R. ",(0,u.jsx)(s.em,{children:"A comparison of classification techniques for the P300 speller"}),". Journal of Neural Engineering, vol. 3, no 4, octobre 2006."]}),"\n",(0,u.jsxs)(s.li,{children:["Hubel D.H. et Wiesel T.N. ",(0,u.jsx)(s.em,{children:"Receptive fields, binocular interaction and functional architecture in the cat's visual cortex"}),". Journal of Physiology, vol. 10, no 1, janvier 1962."]}),"\n",(0,u.jsxs)(s.li,{children:["Martens S.M., Hill N.J., Farquhar J. et Sch\xf6lkopf B. ",(0,u.jsx)(s.em,{children:"Overlap and refractory effects in a brain-computer interface speller based on the visual P300 event-related potential"}),". Journal of Neural Engineering, vol. 6, no 2, mars 2009."]}),"\n"]})]})}function v(e={}){const{wrapper:s}={...(0,d.R)(),...e.components};return s?(0,u.jsx)(s,{...e,children:(0,u.jsx)(x,{...e})}):x(e)}},28453(e,s,n){n.d(s,{R:()=>a,x:()=>l});var i=n(96540);const t={},r=i.createContext(t);function a(e){const s=i.useContext(r);return i.useMemo(function(){return"function"==typeof e?e(s):{...s,...e}},[s,e])}function l(e){let s;return s=e.disableParentContext?"function"==typeof e.components?e.components(t):e.components||t:a(e.components),i.createElement(r.Provider,{value:s},e.children)}}}]);